            { kind: "fill", promptUk: "Допишіть атрибут, що резервує висоту проти зсуву", promptEn: "Fill in the attribute that reserves height against a shift", language: "html", code: "<img src=\"card.webp\" width=\"600\" ___=\"400\" alt=\"\">", accepted: ["height"], caseSensitive: true, explanationUk: "height поруч із width.", explanationEn: "height next to width." },
            { kind: "read", promptUk: "Який вплив цей випадок може мати на CLS?", promptEn: "How can this case affect CLS?", language: "html", code: "<!-- image without dimensions pushes text down -->", options: ["Несподіваний зсув тексту може збільшити CLS", "Він вимірює лише час до першого байта", "Він змінює одиницю розміру бандла", "Він рахує DNS-запити"], optionsEn: ["The unexpected text shift can increase CLS", "It measures only time to first byte", "It changes the bundle-size unit", "It counts DNS requests"], correctIndex: 0, explanationUk: "CLS підсумовує значущі несподівані зсуви за правилами метрики.", explanationEn: "CLS aggregates qualifying unexpected shifts under the metric's rules." }
